{"content":"{
  "name": "deterministic_gridworld_3x3",
  "version": "1.0",
  "description": "A simple deterministic 3x3 grid-world. States are (row, col) pairs, 0-indexed from the top-left corner. All transitions are deterministic: each action moves one cell in the intended direction, and moves that would leave the grid leave the agent in place.",
  "grid": {
    "rows": 3,
    "cols": 3
  },
  "states": [
    [0, 0], [0, 1], [0, 2],
    [1, 0], [1, 1], [1, 2],
    [2, 0], [2, 1], [2, 2]
  ],
  "actions": [
    { "id": 0, "name": "up", "delta": [-1, 0] },
    { "id": 1, "name": "down", "delta": [1, 0] },
    { "id": 2, "name": "left", "delta": [0, -1] },
    { "id": 3, "name": "right", "delta": [0, 1] }
  ],
  "dynamics": {
    "type": "deterministic",
    "transition_rule": "next_state = state + action.delta if the result is within the grid, else next_state = state",
    "off_grid_behavior": "stay_in_place"
  },
  "start_state": [0, 0],
  "terminal_states": [[2, 2]],
  "rewards": {
    "per_step": -1.0,
    "on_reaching_terminal": 0.0,
    "note": "Agent receives -1 per step until the terminal state is reached; the terminal transition itself yields no additional reward."
  },
  "episode": {
    "termination": "agent enters a terminal state",
    "max_steps": 100
  }
}
","path":"rl_contract/environment_spec.json"}

{"content":"import json

path = '/home/agent/workspace/rl_contract/environment_spec.json'
issues = []

# 1. Syntactic validity
try:
    with open(path) as f:
        spec = json.load(f)
    print('JSON syntax: VALID')
except Exception as e:
    print('JSON syntax: INVALID ->', e)
    raise SystemExit(1)

# 2. State space: finite and non-empty
states = spec.get('states')
if not isinstance(states, list):
    issues.append('states is missing or not a list')
elif len(states) == 0:
    issues.append('state space is EMPTY')
else:
    print(f'State space: {len(states)} states (finite, non-empty)')

# 3. Action space: finite and non-empty
actions = spec.get('actions')
if not isinstance(actions, list):
    issues.append('actions is missing or not a list')
elif len(actions) == 0:
    issues.append('action space is EMPTY')
else:
    names = [a.get('name') for a in actions]
    print(f'Action space: {len(actions)} actions (finite, non-empty): {names}')

# 4. Cross-consistency checks
rows, cols = spec['grid']['rows'], spec['grid']['cols']
if isinstance(states, list) and len(states) != rows * cols:
    issues.append(f'states count {len(states)} != grid size {rows}x{cols}={rows*cols}')

state_set = {tuple(s) for s in states} if isinstance(states, list) else set()
start = spec.get('start_state')
if tuple(start) not in state_set:
    issues.append(f'start_state {start} not in state space')
terminals = spec.get('terminal_states', [])
for t in terminals:
    if tuple(t) not in state_set:
        issues.append(f'terminal state {t} not in state space')
if isinstance(actions, list):
    ids = [a.get('id') for a in actions]
    if len(set(ids)) != len(ids):
        issues.append('duplicate action ids')

print()
if issues:
    print('ISSUES FOUND:')
    for i in issues:
        print(' -', i)
else:
    print('ALL CHECKS PASSED: no issues found')
","path":"verify_spec.py"}

{"content":"import json

WS = '/home/agent/workspace/rl_contract'
with open(f'{WS}/environment_spec.json') as f:
    spec = json.load(f)

deltas = {a['id']: tuple(a['delta']) for a in spec['actions']}
rows, cols = spec['grid']['rows'], spec['grid']['cols']
in_grid = lambda s: 0 <= s[0] < rows and 0 <= s[1] < cols
step = lambda s, a: (max(0, min(s[0] + deltas[a][0], rows - 1)),
                     max(0, min(s[1] + deltas[a][1], cols - 1)))

terminals = {tuple(t) for t in spec['terminal_states']}
issues = []

with open(f'{WS}/trajectories.jsonl') as f:
    lines = [l for l in f.read().splitlines() if l.strip()]

print(f'{len(lines)} trajectory lines found')
for i, line in enumerate(lines, 1):
    try:
        t = json.loads(line)
    except Exception as e:
        issues.append(f'T{i}: invalid JSON -> {e}')
        continue

    keys = {'states', 'actions', 'rewards', 'dones'}
    if not keys.issubset(t):
        issues.append(f'T{i}: missing keys {keys - set(t)}')
        continue

    n = len(t['states'])
    lens = {k: len(t[k]) for k in keys}
    if len(set(lens.values())) != 1:
        issues.append(f'T{i}: unequal lengths {lens}')
        continue
    if n == 0:
        issues.append(f'T{i}: empty arrays')
        continue

    # Replay: states[k] is the pre-action state of step k
    if tuple(t['states'][0]) != tuple(spec['start_state']):
        issues.append(f"T{i}: first state {t['states'][0]} != start {spec['start_state']}")
    prev_r = None
    for k in range(n):
        s = tuple(t['states'][k])
        a = t['actions'][k]
        if not in_grid(s):
            issues.append(f'T{i} step {k}: state {s} outside grid')
            break
        if a not in deltas:
            issues.append(f'T{i} step {k}: invalid action id {a}')
            break
        nxt = step(s, a)
        done = bool(t['dones'][k])
        expected_done = nxt in terminals
        if done != expected_done:
            issues.append(f'T{i} step {k}: done={done} but next {nxt} terminal={expected_done}')
        expected_r = spec['rewards']['per_step']
        if t['rewards'][k] != expected_r:
            issues.append(f'T{i} step {k}: reward {t["rewards"][k]} != {expected_r}')
        if done and nxt not in terminals:
            issues.append(f'T{i} step {k}: terminal flag but {nxt} not terminal')
        # done must only be on last step
        if done and k != n - 1:
            issues.append(f'T{i} step {k}: done before last step')
    print(f'T{i}: {n} steps, lengths equal, replayed OK')

print()
if issues:
    print('ISSUES:')
    for x in issues:
        print(' -', x)
else:
    print('ALL TRAJECTORIES CONSISTENT WITH SPEC')
","path":"verify_traj.py"}

