WS = '/home/agent/workspace/rl_contract'
with open(f'{WS}/environment_spec.json') as f:
    spec = json.load(f)

deltas = {a['id']: tuple(a['delta']) for a in spec['actions']}
rows, cols = spec['grid']['rows'], spec['grid']['cols']
in_grid = lambda s: 0 <= s[0] < rows and 0 <= s[1] < cols
step = lambda s, a: (max(0, min(s[0] + deltas[a][0], rows - 1)),
                     max(0, min(s[1] + deltas[a][1], cols - 1)))

terminals = {tuple(t) for t in spec['terminal_states']}
issues = []

with open(f'{WS}/trajectories.jsonl') as f:
    lines = [l for l in f.read().splitlines() if l.strip()]

print(f'{len(lines)} trajectory lines found')
for i, line in enumerate(lines, 1):
    try:
        t = json.loads(line)
    except Exception as e:
        issues.append(f'T{i}: invalid JSON -> {e}')
        continue

    keys = {'states', 'actions', 'rewards', 'dones'}
    if not keys.issubset(t):
        issues.append(f'T{i}: missing keys {keys - set(t)}')
        continue

    n = len(t['states'])
    lens = {k: len(t[k]) for k in keys}
    if len(set(lens.values())) != 1:
        issues.append(f'T{i}: unequal lengths {lens}')
        continue
    if n == 0:
        issues.append(f'T{i}: empty arrays')
        continue

    # Replay: states[k] is the pre-action state of step k
    if tuple(t['states'][0]) != tuple(spec['start_state']):
        issues.append(f"T{i}: first state {t['states'][0]} != start {spec['start_state']}")
    prev_r = None
    for k in range(n):
        s = tuple(t['states'][k])
        a = t['actions'][k]
        if not in_grid(s):
            issues.append(f'T{i} step {k}: state {s} outside grid')
            break
        if a not in deltas:
            issues.append(f'T{i} step {k}: invalid action id {a}')
            break
        nxt = step(s, a)
        done = bool(t['dones'][k])
        expected_done = nxt in terminals
        if done != expected_done:
            issues.append(f'T{i} step {k}: done={done} but next {nxt} terminal={expected_done}')
        expected_r = spec['rewards']['per_step']
        if t['rewards'][k] != expected_r:
            issues.append(f'T{i} step {k}: reward {t["rewards"][k]} != {expected_r}')
        if done and nxt not in terminals:
            issues.append(f'T{i} step {k}: terminal flag but {nxt} not terminal')
        # done must only be on last step
        if done and k != n - 1:
            issues.append(f'T{i} step {k}: done before last step')
    print(f'T{i}: {n} steps, lengths equal, replayed OK')

print()
if issues:
    print('ISSUES:')
    for x in issues:
        print(' -', x)
else:
    print('ALL TRAJECTORIES CONSISTENT WITH SPEC')
","path":"verify_traj.py"}

{"content":"import json

WS = '/home/agent/workspace/rl_contract'
with open(f'{WS}/environment_spec.json') as f:
    spec = json.load(f)

valid_states = {tuple(s) for s in spec['states']}
valid_actions = {a['id'] for a in spec['actions']}

with open(f'{WS}/trajectories.jsonl') as f:
    lines = [l for l in f.read().splitlines() if l.strip()]

n_traj = len(lines)
total_transitions = 0
problems = []

for i, line in enumerate(lines, 1):
    t = json.loads(line)  # would raise on invalid JSON

    lens = {k: len(t.get(k, [])) for k in ('states', 'actions', 'rewards', 'dones')}
    if len(set(lens.values())) != 1:
        problems.append(f'T{i}: MISMATCHED array lengths: {lens}')
        continue  # can't safely index misaligned arrays

    n = lens['states']
    total_transitions += n

    for k, s in enumerate(t['states']):
        if tuple(s) not in valid_states:
            problems.append(f'T{i} step {k}: invalid state {s}')
    for k, a in enumerate(t['actions']):
        if a not in valid_actions:
            problems.append(f'T{i} step {k}: invalid action {a}')

    print(f'T{i}: {n} transitions, lengths {lens["states"]} across all arrays')

print()
print(f'Trajectories:        {n_traj}')
print(f'Total transitions:   {total_transitions}')
if problems:
    print(f'Problems found:      {len(problems)}')
    for p in problems:
        print(' -', p)
else:
    print('Array lengths:       all matched within every trajectory')
    print('States/actions:      all valid (no invalid values)')
","path":"inspect_traj.py"}

{"content":"#!/usr/bin/env python3
"""Tabular Q-learning for the 3x3 grid-world contract.

Loads environment_spec.json (state/action spaces, terminals) and
trajectories.jsonl (demonstrations), runs tabular Q-learning over the
transitions, and writes the resulting greedy policy to policy.json.
Standard library only.
"""

import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SPEC_PATH = os.path.join(HERE, "environment_spec.json")
TRAJ_PATH = os.path.join(HERE, "trajectories.jsonl")
POLICY_PATH = os.path.join(HERE, "policy.json")

ALPHA = 0.5    # learning rate
GAMMA = 0.9    # discount factor
PASSES = 50    # sweeps over the dataset


def skey(state):
    return f"{state[0]},{state[1]}"


def load_data():
    with open(SPEC_PATH) as f:
        spec = json.load(f)
    trajectories = []
    with open(TRAJ_PATH) as f:
        for line in f:
            if line.strip():
                trajectories.append(json.loads(line))
    return spec, trajectories


def train(spec, trajectories):
    states = [tuple(s) for s in spec["states"]]
    action_ids = [a["id"] for a in spec["actions"]]
    terminals = {tuple(t) for t in spec["terminal_states"]}

    q = {s: {a: 0.0 for a in action_ids} for s in states}

    for _ in range(PASSES):
        for traj in trajectories:
            steps = list(zip(traj["states"], traj["actions"],
                             traj["rewards"], traj["dones"]))
            for k, (s, a, r, done) in enumerate(steps):
                s, a = tuple(s), int(a)
                if done:
                    target = r  # terminal step: no bootstrap
                else:
                    nxt = tuple(steps[k + 1][0])  # deterministic env: next pre-action state
                    target = r + GAMMA * max(q[nxt].values())
                q[s][a] += ALPHA * (target - q[s][a])
    return states, action_ids, terminals, q


def extract(states, action_ids, terminals, q):
    policy, values = {}, {}
    for s in states:
        if s in terminals:
            policy[skey(s)], values[skey(s)] = None, 0.0
        else:
            best = max(action_ids, key=lambda a: q[s][a])  # ties -> lowest id
            policy[skey(s)] = best
            values[skey(s)] = round(q[s][best], 6)
    return policy, values


def main():
    spec, trajectories = load_data()
    states, action_ids, terminals, q = train(spec, trajectories)
    policy, values = extract(states, action_ids, terminals, q)

    result = {
        "algorithm": "tabular_q_learning",
        "hyperparameters": {"alpha": ALPHA, "gamma": GAMMA, "passes": PASSES},
        "key_format": "row,col",
        "action_order": action_ids,
        "policy": policy,
        "state_values": values,
        "q_table": {skey(s): [q[s][a] for a in action_ids] for s in states},
        "trained_on": {
            "trajectories": len(trajectories),
            "transitions": sum(len(t["actions"]) for t in trajectories),
        },
    }
    with open(POLICY_PATH, "w") as f:
        json.dump(result, f, indent=2)

    print(f"Trained on {len(trajectories)} trajectories "
          f"({result['trained_on']['transitions']} transitions), {PASSES} passes.")
    print(f"Saved policy to {POLICY_PATH}")
    print("Greedy policy (row,col -> action):")
    for s in states:
        print(f"  {skey(s)} -> {policy[skey(s)]}")


if __name__ == "__main__":
    main()
","path":"rl_contract/train_policy.py"}

